using F = StrataLint.Scribe.FormulaDsl;
using static StrataLint.Scribe.FormulaDsl;
using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Observer;
internal sealed class NativeSerialEffectiveDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Observer/NativeSerialEffective.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "NativeSerialEffective", H("NativeSerialEffective"), Blocks(
            Entry("OriginalEvent", "Acquired external event", "A finite event records the actual update epoch or the actual epoch, finite physical address and four-valued reply of a Read. Repetition and chronological order are retained.", DescribeRole.Definition),
            Entry("OriginalState", "Complete finite accessible selector state", "The four components encode common finite input, deterministic accessible workspace, certified epoch and the complete acquired chronological record. Natural encodings permit arbitrary finite strings and finite records; there is no bound on their lengths. The state is common at the fixed entrance, rather than chosen separately for each source.", DescribeRole.Definition),
            Entry("originalReplyCode", "Effective four-valued encoding", "Alpha, beta, branch and absent have codes zero, one, two and three.", DescribeRole.Definition),
            Entry("afterOriginalRead", "Actual Read state transition", "Append the actual epoch, submitted address and actual reply without changing the register or epoch; select the designated accessible workspace.", DescribeRole.Definition),
            Entry("afterOriginalUpdate", "Actual update state transition", "Append the update and increment the epoch while physical execution applies substitution to the same register.", DescribeRole.Definition),
            Entry("OriginalAction", "Independent source selector actions", "A source action is a finite Read address with four workspace continuations, an update continuation, or a finite output. These sum/product carriers have the standard Primcodable representation. All four Read continuations may be the same saved workspace; the next selector evaluation can perform arbitrary reply-dependent computation from the appended record.", DescribeRole.Definition),
            Entry("originalRead", "Read action constructor", "The finite address is computed by the partial selector; no fixed address bound is supplied.", DescribeRole.Definition),
            Entry("originalUpdate", "Update action constructor", "A real same-register substitution with a finite workspace continuation.", DescribeRole.Definition),
            Entry("originalStop", "Absorbing output action", "A Halt returns the entire finite output and ends this invocation.", DescribeRole.Definition),
            Entry("originalContinuation", "Reply-directed workspace", "The actual four-valued reply selects the continuation, and is also appended to the full record.", DescribeRole.Definition),
            Entry("OriginalEffectiveService", "Partial-recursive original selector semantics", "Effectiveness means the standard mathlib Partrec predicate on the independently specified finite input, workspace, epoch and full history carrier. This is the ordinary partial-recursive interpretation of a deterministic effective selector on finite data, not a field asserting representation in a packet machine. Divergence is permitted on unreachable histories. A sourcewise terminating service supplies finite OriginalRun witnesses only for its actual source fiber.", DescribeRole.Definition),
            Entry("OriginalRun", "Independent original boundary execution", "Selection is membership in a partial computation. The source rules append every physical event, perform actual substitution, query the actual current register, and stop with the full output. Local selector computation is not an extra physical event.", DescribeRole.Definition),
            Entry("originalSelectorCode", "Exact partial-recursive realization", "The pinned Nat.Partrec.Code.exists_code realizes the selector on encoded finite states and outputs. Choosing one fixed code is an existential program choice, not runtime totalization of its partial evaluation.", DescribeRole.Definition),
            Entry("OriginalCodeRealization", "Explicit code realization", "A caller supplies a concrete Nat.Partrec.Code and an equality at every genuine encoded OriginalState: eval code (encode s) equals the encoded partial action selected at s. No equality is required on invalid natural representations. Every original partial-recursive selector has such a code by originalSelectorCode_spec specialized at encode s and encodek; the choice may be noncomputable. This is existence of one program for each service, with no uniform executable extraction from a proposition. The proof is not consulted by the executable evaluator.", DescribeRole.Definition),
            Entry("evalOriginalActionFromCode", "Executable finite-code evaluator", "At finite stage j evaluate an explicitly supplied partial-recursive code with evaln fuel 2^j and decode one original action. A miss advances only the stage. Cofinality follows from evaln_mono and j < 2^j, so every finite sufficient raw fuel is eventually exceeded. The raw evaluator requires its encoded input to be below its fuel; the schedule permits execution on arbitrary finite histories without a global bound. This definition contains no classical choice and can be run directly; no runtime complexity estimate is asserted.", DescribeRole.Definition),
            Entry("evalOriginalActionCode", "Realized finite-code evaluator", "The executable evaluator selected by an OriginalCodeRealization is the supplied code evaluator, with the realization equation available only for the soundness and completeness bridge.", DescribeRole.Definition),
            Entry("evalOriginalActionCode_sound", "Realized action soundness", "At every stage, a decoded action returned on a genuine source state belongs to that state's independently specified partial selector. The proof directly reuses evaln_sound and the genuine-state realization equation; the boundary-prefix simulation consumes it to rule out any earlier different action.", DescribeRole.Theorem),
            Entry("evalOriginalActionCode_complete", "Cofinal action completeness", "Every actual selected action is returned at some finite stage. evaln_complete supplies raw fuel, evaln_mono lifts it to 2^stage, and encodek recovers the action. The native boundary induction consumes this witness separately for Stop, ApplyRho and Read, without a common runtime bound.", DescribeRole.Theorem),
            Entry("evalOriginalAction", "Bounded evaluator", "Only total finite-fuel evaln is executed. Its soundness and completeness are reused directly from pinned mathlib; a reached action has some finite sufficient fuel, while an unreachable diverging state need never yield an action.", DescribeRole.Definition),
            Entry("originalControl", "Encoded evaluator configuration", "Pair the source state code with a finite controller counter. The original chosen-code controller uses it as raw fuel; the explicit executable backend uses it as stage j and queries raw fuel 2^j. Both reset the counter to zero after each physical action.", DescribeRole.Definition),
            Entry("originalNativeControl", "Total source-blind microsteps", "Decode the finite state and run one bounded evaluator attempt. Failure inserts a Local step with increased fuel; success submits exactly the selected physical action. No tree, timing, identity, equality, reset or clone port enters control.", DescribeRole.Definition),
            Entry("originalNativeControlFromCode", "Executable finite-code controller", "Run one source-blind native microstep from an explicit code. Failed finite evaluation emits only a local evaluator step; successful Read, ApplyRho and Stop actions use the same source-state transitions as the original controller.", DescribeRole.Definition),
            Entry("originalNativeControlCode", "Realized finite-code controller", "The controller attached to a proved explicit code realization. Its runtime behavior is entirely determined by the code, while the realization proof establishes correspondence with the original partial selector.", DescribeRole.Definition),
            Entry("eraseEvaluatorSteps", "External trace erasure", "Remove only Local evaluator steps, retaining all actual substitutions and every repeated physical Read and reply.", DescribeRole.Definition),
            Entry("ExternalObservation", "Typed external observation", "The observation type explicitly distinguishes update, Read and Halt carrying the complete output.", DescribeRole.Definition),
            Entry("externalEvents", "External event projection", "Project native traces to external observations by removing local work only.", DescribeRole.Definition),
            Entry("terminalObservation", "Terminal whole-output observation", "Append exactly one Halt with the full output to the chronological external events.", DescribeRole.Definition),
            Entry("original_service_simulation", "General original-selector simulation", "The bounded evaluator is certified Computable by exact composition of primrec_evaln and decoding. For every terminating execution of any partial-recursive original selector, one fixed total source-blind evaluator control has a finite native run on the identical current register and certified epoch. Increasing-fuel search terminates separately at each reached boundary. Erasure preserves the exact external trace, repeated Read list and terminal observation including Halt and the entire output. No uniform local, workspace, update or runtime bound is used.", DescribeRole.Theorem),
            Entry("original_code_service_simulation", "Direct executable original-selector simulation", "For a supplied finite code and its genuine-state realization equation, the exponential-stage evaluator is Computable by Nat.Primrec.pow, Primrec2.unpaired', primrec_evaln and decoding. For every OriginalRun, cofinal completeness and the boundary induction give a finite native trace on the identical register and certified epoch. Erasure retains the exact suffix, every repeated paid Read, real ApplyRho, terminal Halt and entire output. Common input, workspace, epoch and retained history are unrestricted finite data. Partial divergence away from reached states remains allowed, and no uniform runtime, address, workspace or totality bound is added.", DescribeRole.Theorem),
            Entry("Packet", "Encoded machine instruction", "An unrestricted natural number encodes local machine state. A finite packet supplies an opcode, successor or output code, a finite physical address and four continuation states. Neither the state set nor address domain is bounded.", DescribeRole.Definition),
            Entry("EffectiveService", "Encoded source-free service", "The one-step interpreter is computable. Local divergence remains an unbounded sequence of local steps. The output map interprets terminal output codes in the semantic output type; the lower-bound class also permits arbitrary such interpretations. An effective finite-output decoder is one allowed interpretation; arbitrary output maps need not themselves be effective. Common input is part of the fixed initial control, never a hidden source argument.", DescribeRole.Definition),
            Entry("continuation", "Literal reply continuation", "The four continuation entries are selected by alpha, beta, branch and absent respectively. Selecting a continuation consumes exactly the reply returned by the submitted physical Read.", DescribeRole.Definition),
            Entry("compile", "Exact four-operation bridge", "Compilation only maps one encoded machine instruction to its native Local, Read, ApplyRho or Stop case. It performs no next-boundary search and constructs no observation tree.", DescribeRole.Definition),
            Entry("ServiceRun", "Direct encoded-service execution", "The direct rules operate on the actual original physical register. Read invokes the literal port once; ApplyRho performs real substitution. Every action, epoch, address, reply and entire terminal output is retained.", DescribeRole.Definition),
            Entry("effective_service_inclusion", "Trace-preserving effective-service inclusion", "Every direct encoded-service run is a native serial run on exactly the same register with exactly the same full action trace and output. Thus every chronological call and update is preserved one for one. The native lower-bound class is broader: its control types and transition functions need not be computable.", DescribeRole.Theorem)
        )));
    private static DocumentBlock Entry(string name, string title, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("nativeserialeffective-" + name.Replace("_", "-").Replace(".", "-").ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(title),
            role == DescribeRole.Theorem ? StatementSource.FromAuthor(Disp(Statement(name))) : StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);

    private static Formula Statement(string name) => name switch
    {
        "original_service_simulation" => All("O",Seq(V("Type"),Sp,OpenBracket,Call("Primcodable",V("O")),CloseBracket),All("S",Call("OriginalEffectiveService",V("O")),All("s",V("OriginalState"),All("r",V("Source"),All("t",V("Trace"),All("o",V("O"),Imp(Call("OriginalRun",V("S"),V("s"),V("r"),V("t"),V("o")),And(Call("Computable",Call("uncurry",Call("evalOriginalAction",V("S")))),Some("n",V("Trace"),And(Call("Run",Call("originalNativeControl",V("S")),Call("originalControl",V("s"),D(0)),Call("epoch",V("s")),V("r"),V("n"),V("o")),EqOf(Call("eraseEvaluatorSteps",V("n")),V("t")),EqOf(Call("reads",V("n")),Call("reads",V("t"))),EqOf(Call("terminalObservation",V("n"),V("o")),Call("terminalObservation",V("t"),V("o"))))))))))))),
        "original_code_service_simulation" => All("O",Seq(V("Type"),Sp,OpenBracket,Call("Primcodable",V("O")),CloseBracket),All("S",Call("OriginalEffectiveService",V("O")),All("R",Call("OriginalCodeRealization",V("S")),All("s",V("OriginalState"),All("r",V("Source"),All("t",V("Trace"),All("o",V("O"),Imp(Call("OriginalRun",V("S"),V("s"),V("r"),V("t"),V("o")),And(Call("Computable",Call("uncurry",Call("evalOriginalActionCode",V("R")))),Some("n",V("Trace"),And(Call("Run",Call("originalNativeControlCode",V("R")),Call("originalControl",V("s"),D(0)),Call("epoch",V("s")),V("r"),V("n"),V("o")),EqOf(Call("eraseEvaluatorSteps",V("n")),V("t")),EqOf(Call("reads",V("n")),Call("reads",V("t"))),EqOf(Call("terminalObservation",V("n"),V("o")),Call("terminalObservation",V("t"),V("o")))))))))))))),
        "evalOriginalActionCode_sound" => All("O",Seq(V("Type"),Sp,OpenBracket,Call("Primcodable",V("O")),CloseBracket),All("S",Call("OriginalEffectiveService",V("O")),All("R",Call("OriginalCodeRealization",V("S")),All("s",V("OriginalState"),All("j",V("Nat"),All("a",Call("OriginalAction",V("O")),Imp(EqOf(Call("evalOriginalActionCode",V("R"),V("j"),Call("encode",V("s"))),Call("some",V("a"))),Call("mem",V("a"),Call("select",V("S"),V("s")))))))))),
        "evalOriginalActionCode_complete" => All("O",Seq(V("Type"),Sp,OpenBracket,Call("Primcodable",V("O")),CloseBracket),All("S",Call("OriginalEffectiveService",V("O")),All("R",Call("OriginalCodeRealization",V("S")),All("s",V("OriginalState"),All("a",Call("OriginalAction",V("O")),Imp(Call("mem",V("a"),Call("select",V("S"),V("s"))),Some("j",V("Nat"),EqOf(Call("evalOriginalActionCode",V("R"),V("j"),Call("encode",V("s"))),Call("some",V("a")))))))))),
        "effective_service_inclusion" => All("O",V("Type"),All("S",Call("EffectiveService",V("O")),All("c,e",V("Nat"),All("r",V("Source"),All("t",V("Trace"),All("o",V("O"),Imp(Call("ServiceRun",V("S"),V("c"),V("e"),V("r"),V("t"),V("o")),Call("Run",Call("compile",V("S")),V("c"),V("e"),V("r"),V("t"),V("o"))))))))),
        _ => throw new ArgumentException(name)
    };

    private static Formula EqOf(Formula a, Formula b) => Seq(a,Sp,Eq,Sp,b);
    private static Formula And(params Formula[] fs) => Seq(fs.Select((f,i) => i == 0 ? Par(f) : Seq(Sp,Land,Sp,Par(f))).ToArray());
    private static Formula Some(string n, Formula t, Formula b) => Seq(Exists,Sp,V(n),Colon,Sp,t,Comma,Sp,Par(b));
    private static Formula V(string n) => F.Id(n);
    private static Formula Par(Formula f) => Seq(Open, f, Close);
    private static Formula Call(string n, params Formula[] args) => new Formula.Apply(Seq(Operatorname, Grp(V(n))), [.. args]);
    private static Formula Imp(Formula a, Formula b) => Seq(Par(a), Sp, Implies, Sp, Par(b));
    private static Formula All(string ns, Formula t, Formula b) => Seq(Forall, Sp,
        Seq(ns.Split(',').Select((n, i) => i == 0 ? V(n) : Seq(Comma, Sp, V(n))).ToArray()), Colon, Sp, t, Comma, Sp, Par(b));
}
